+pub(super) enum ProviderSessionState {
+    Available(NativeYoloChannel),
+    MissingCapability { loaded: bool },
+    Unsupported,
+}
+
+#[derive(Clone, Copy)]
+pub(super) struct ConfigSpec {
+    pub id: &'static str,
+    pub category: &'static str,
+    pub enable_value: &'static str,
